message.content:
{
  "candidate_edge_types": [
    {
      "name": "USES_RESOURCE_IDENTIFIERS_FROM_PRIOR_OBSERVATION",
      "definition": "An agent action retrieves, reads, or processes a resource using file names, identifiers, or resource references that were provided in an earlier observation.",
      "source_description": "An earlier observation that enumerates available files, identifiers, or items that can be accessed.",
      "target_description": "A subsequent agent action that consumes one or more of those identifiers to access or process the corresponding resource."
    },
    {
      "name": "SELECTS_TOOL_BASED_ON_AVAILABILITY_OBSERVATION",
      "definition": "An agent selects or avoids a tool or capability in a subsequent action based on an earlier observation of which tools are installed or available.",
      "source_description": "An earlier observation indicating the availability or absence of specific tools, programs, or capabilities.",
      "target_description": "A subsequent agent action that uses an available tool or avoids an unavailable one."
    },
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a failure that was identified during an earlier execution step.",
      "source_description": "An earlier observed execution failure or error.",
      "target_description": "A subsequent agent action intended to resolve or work around that failure."
    },
    {
      "name": "GENERALIZES_VERIFIED_METHOD_TO_BATCH",
      "definition": "After a method or capability has been verified on a single probe item, the agent applies the same method to process a batch of remaining items.",
      "source_description": "An observation that a method or capability succeeded on a test or probe item.",
      "target_description": "A subsequent agent action that applies the verified method to multiple items."
    },
    {
      "name": "EXTRACTS_DATA_COMPONENT_FROM_PRIOR_OBSERVATION",
      "definition": "An agent decision or action isolates a specific data element from a larger record in an earlier observation for subsequent use.",
      "source_description": "An earlier observation containing a composite record or mixed data.",
      "target_description": "A subsequent agent thought or action that extracts and uses a specific component from that observation."
    }
  ]
}

